import React, { useState, useEffect, useCallback } from 'react';
import styles from './TerminalCursor.module.css';

// Metallic-looking symbols (some look like droplets, others are sleek)
const METAL_CHARS = ['•', '◉', '○', '◆', '◈', '⬤', '💧', '⚙️', '✨', '▸', '◂', '⎯', '⏤'];

const TerminalCursor = () => {
  const [particles, setParticles] = useState([]);
  const [isTouchDevice, setIsTouchDevice] = useState(false);

  const addParticle = useCallback((x, y) => {
    const id = Date.now() + Math.random();
    const char = METAL_CHARS[Math.floor(Math.random() * METAL_CHARS.length)];
    
    // Random stretch direction for liquid effect
    const stretchX = (Math.random() - 0.5) * 1.5;
    const stretchY = Math.random() * 2 + 0.5;
    
    setParticles(prev => [...prev, { 
      id, 
      x, 
      y, 
      char,
      stretchX,
      stretchY,
      delay: Math.random() * 0.3,
      rotation: Math.random() * 360
    }]);
    
    setTimeout(() => {
      setParticles(prev => prev.filter(p => p.id !== id));
    }, 1000);
  }, []);

  useEffect(() => {
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    let lastMove = 0;
    const handleMouseMove = (e) => {
      const now = Date.now();
      if (now - lastMove > 40) { // Slightly faster for liquid feel
        addParticle(e.clientX, e.clientY);
        lastMove = now;
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [addParticle]);

  if (isTouchDevice) return null;

  return (
    <>
      {particles.map(p => (
        <span
          key={p.id}
          className={styles.liquidMetalChar}
          style={{
            left: `${p.x}px`,
            top: `${p.y}px`,
            '--stretch-x': p.stretchX,
            '--stretch-y': p.stretchY,
            '--delay': `${p.delay}s`,
            '--rotation': `${p.rotation}deg`,
          }}
        >
          {p.char}
        </span>
      ))}
    </>
  );
};

export default TerminalCursor;
